@@ -123,6 +123,14 @@ func (authService *AuthService) BindOAuth(
 		return "", err
 	}

+	// 在签发 state JWT 前校验，避免非法 redirect 进入 state 后只能在回调阶段才被发现
+	// （GHSA-p64j-f4x9-wq66）。空值保留旧行为：在回调阶段统一拦截。
+	if redirectURI != "" {
+		if _, err := authService.parseAndValidateClientRedirect(redirectURI); err != nil {
+			return "", err
+		}
+	}
+
 	state, nonce, err := jwtUtil.GenerateOAuthState(
 		string(authModel.OAuth2ActionBind),
 		userID,
@@ -147,6 +155,14 @@ func (authService *AuthService) GetOAuthLoginURL(provider string, redirectURI st
 		return "", err
 	}

+	// 在签发 state JWT 前校验，避免非法 redirect 进入 state 后只能在回调阶段才被发现
+	// （GHSA-p64j-f4x9-wq66）。空值保留旧行为：在回调阶段统一拦截。
+	if redirectURI != "" {
+		if _, err := authService.parseAndValidateClientRedirect(redirectURI); err != nil {
+			return "", err
+		}
+	}
+
 	state, nonce, err := jwtUtil.GenerateOAuthState(
 		string(authModel.OAuth2ActionLogin),
 		"",
@@ -472,14 +488,24 @@ func (authService *AuthService) parseAndValidateClientRedirect(redirect string)
 	if len(allowed) == 0 {
 		return nil, errors.New(commonModel.INVALID_PARAMS)
 	}
+	// 按 RFC 6749 §3.1.2 进行 scheme+host+path 的精确比对：仅校验 scheme+host
+	// 会让攻击者把同源任意路径塞进 state（GHSA-p64j-f4x9-wq66），事后通过 Referer
+	// 泄漏、第三方分析脚本、宿主上的 open-redirect 链路把一次性 exchange code 转给
+	// 攻击者。query/fragment 不参与比对：服务器会在校验通过后向 redirect URL 追加
+	// ?code=...，允许调用方携带额外查询参数。
+	redirectNorm := strings.ToLower(redirectURL.Scheme) + "://" +
+		strings.ToLower(redirectURL.Host) +
+		redirectURL.Path
 	matched := false
 	for _, item := range allowed {
 		allowURL, parseErr := url.Parse(strings.TrimSpace(item))
 		if parseErr != nil || allowURL == nil || allowURL.Host == "" {
 			continue
 		}
-		if strings.EqualFold(redirectURL.Scheme, allowURL.Scheme) &&
-			strings.EqualFold(redirectURL.Host, allowURL.Host) {
+		allowNorm := strings.ToLower(allowURL.Scheme) + "://" +
+			strings.ToLower(allowURL.Host) +
+			allowURL.Path
+		if redirectNorm == allowNorm {
 			matched = true
 			break
 		}
diff --git a/internal/service/auth/oauth_service_test.go b/internal/service/auth/oauth_service_test.go
index 470df5de5..b0f7ac3fb 100644
--- a/internal/service/auth/oauth_service_test.go
+++ b/internal/service/auth/oauth_service_test.go
@@ -33,3 +33,19 @@ func TestParseAndValidateClientRedirect_Denied(t *testing.T) {
 		t.Fatalf("expected deny redirect")
 	}
 }
+
+// 防 GHSA-p64j-f4x9-wq66：scheme+host 相同但 path 不在白名单内必须拒绝，否则
+// 攻击者可借助同源任意路径上的 Referer/分析脚本/open-redirect 截获一次性
+// exchange code。
+func TestParseAndValidateClientRedirect_PathMismatchDenied(t *testing.T) {
+	cfg := config.Config()
+	cfg.Auth.Redirect.AllowedReturnURLs = []string{"https://app.example.com/auth"}
+
+	svc := &AuthService{}
+	_, err := svc.parseAndValidateClientRedirect(
+		"https://app.example.com/attacker-chosen-path",
+	)
+	if err == nil {
+		t.Fatalf("expected deny redirect with mismatched path")
+	}
+}
